import base64
new_fn = base64.b64decode("").decode('utf-8')

c = open('app/pfd/page.tsx','r',encoding='utf-8').read()

old_start = "  const exportExcel = async () => {\n    const xlsx = await import('xlsx');"
old_end = "    xlsx.writeFile(wb, `PFD_${header.item || 'export'}_${header.revLevel || 'R0'}.xlsx`);\n  };"

old_fn = c[c.find(old_start):c.find(old_end)+len(old_end)]
c = c.replace(old_fn, new_fn)
open('app/pfd/page.tsx','w',encoding='utf-8').write(c)
print('Done')
